def gen(rng):
    def build(n, vals):
        perm = [0] + rng.sample(range(1, n), n - 1) if n > 1 else [0]
        lines = [None] * n
        for p in range(n):
            l, r = 2 * p + 1, 2 * p + 2
            lines[perm[p]] = '%d %d %d' % (vals[p], perm[l] if l < n else -1, perm[r] if r < n else -1)
        return str(n) + '\n' + '\n'.join(lines)
    tests = []
    for n in list(range(1, 15)) + [15, 16, 17, 20]:
        tests.append(build(n, [rng.randint(1, 99) for _ in range(n)]))
    tests.append(build(2000, [rng.randint(1, 10**9) for _ in range(2000)]))
    tests.append(build(1023, [rng.randint(1, 10**9) for _ in range(1023)]))
    for n in (65535, 65536, 100000, 98303):
        tests.append(build(n, [rng.randint(1, 10**9) for _ in range(n)]))
    return tests
